(()=>{
let resultKey=null,resultPage=0;
const body=document.body,main=document.querySelector('main'),messages=document.getElementById('messages');
const data=HerpBusinessReference.data;
function activate(){body.classList.add('ai-session');body.classList.remove('conversation-entry','warehouse-conversation');document.getElementById('conversation-recommendations')?.remove();document.getElementById('warehouse-recommendations')?.remove();window.scrollTo(0,0)}
function reset(){body.classList.remove('ai-session','ai-has-result','ai-result-expanded');document.getElementById('query-result-pane')?.remove();document.getElementById('query-pane-divider')?.remove();resultKey=null;resultPage=0;body.style.removeProperty('--query-share')}
const newBase=openNewConversation;openNewConversation=function(){reset();newBase()};
for(const name of ['setModule','openActivityBoard','openAutomationTasks','openMySpace','openIMSettings','showRoleSelection']){const base=window[name];if(typeof base==='function')window[name]=function(...args){reset();return base.apply(this,args)}}
const messageBase=addMessage;addMessage=function(text,user){activate();messageBase(text,user);if(!user){const author=messages.lastElementChild?.querySelector('strong');if(author)author.textContent=document.getElementById('agent-toggle').dataset.selectedAgent?document.getElementById('agent-toggle').textContent.replace(/^✧\s*/,'').split(' · ')[0]:'H ERP 助手'}};
function renderPane(){const pane=document.getElementById('query-result-pane');const d=data[resultKey];pane.querySelector('h2').textContent=d.title;pane.querySelector('.query-result-content').innerHTML=HerpBusinessReference.table(resultKey,resultPage)+'<p class="query-result-caption">示例业务数据 · 可在左侧继续对话</p>';pane.querySelectorAll('[data-page]').forEach(b=>b.onclick=()=>{resultPage=Number(b.dataset.page);renderPane()});pane.querySelectorAll('[data-query-row]').forEach(b=>b.onclick=()=>{const row=d.rows[Number(b.dataset.queryRow)];suggest('请解释'+row[0]+'的'+d.title+'结果。')})}
function openPane(key){activate();resultKey=key;resultPage=0;let pane=document.getElementById('query-result-pane');if(!pane){const divider=document.createElement('div');divider.id='query-pane-divider';divider.className='query-pane-divider';divider.tabIndex=0;divider.setAttribute('role','separator');divider.setAttribute('aria-label','调整对话区与业务结果宽度');divider.setAttribute('aria-orientation','vertical');divider.setAttribute('aria-valuemin','25');divider.setAttribute('aria-valuemax','65');divider.setAttribute('aria-valuenow','42');const setExpanded=expanded=>{body.classList.toggle('ai-result-expanded',expanded);const b=document.querySelector('#query-result-pane [data-expand]');if(b){b.textContent=expanded?'⛶ 还原':'⛶ 放大';b.setAttribute('aria-expanded',String(expanded));b.setAttribute('aria-label',expanded?'还原业务页面':'放大业务页面')}};const resize=x=>{const box=main.getBoundingClientRect(),share=(x-box.left)/box.width;if(share<=.25){setExpanded(true);divider.setAttribute('aria-valuenow','25');return}setExpanded(false);share=Math.min(.65,Math.max(.25,share));body.style.setProperty('--query-share',share);divider.setAttribute('aria-valuenow',Math.round(share*100))};divider.onkeydown=e=>{if(!['ArrowLeft','ArrowRight'].includes(e.key))return;e.preventDefault();const box=main.getBoundingClientRect(),percent=Number(divider.getAttribute('aria-valuenow'))+(e.key==='ArrowLeft'?-2:2);resize(box.left+box.width*percent/100)};divider.onpointerdown=e=>{divider.setPointerCapture(e.pointerId);divider.onpointermove=m=>resize(m.clientX);divider.onpointerup=()=>{divider.onpointermove=null}};main.append(divider);pane=document.createElement('section');pane.id='query-result-pane';pane.className='query-result-pane';pane.setAttribute('aria-label','业务查询结果');pane.innerHTML='<header class="query-result-header"><h2></h2><div><button type="button" data-expand aria-label="放大业务页面" aria-expanded="false">⛶ 放大</button><button type="button" data-close aria-label="关闭业务页面">×</button></div></header><div class="query-result-content"></div>';main.append(pane);pane.querySelector('[data-close]').onclick=()=>{pane.hidden=true;divider.hidden=true;body.classList.remove('ai-has-result','ai-result-expanded');promptBox.focus()};pane.querySelector('[data-expand]').onclick=()=>{setExpanded(!body.classList.contains('ai-result-expanded'))}}pane.hidden=false;document.getElementById('query-pane-divider').hidden=false;body.classList.add('ai-has-result');renderPane()}
function addReport(key,show=false){messages.querySelector('.query-run-report')?.remove();const d=data[key],report=document.createElement('section');report.className='query-run-report';report.setAttribute('aria-label','智能体运行进展');report.innerHTML='<div class="query-progress"><div class="query-progress-head"><strong>运行进展</strong><span>已完成</span></div><ol class="query-steps">'+['读取业务数据','校验与整理','生成结果','完成反馈'].map((s,i)=>'<li><i>'+(i+1)+'</i><span>'+s+'</span></li>').join('')+'</ol><div class="query-current-node">当前节点：查询与整理结果</div></div><div class="query-complete"><strong>✓ 运行已完成，结果已送达</strong><p>你可以查看结果，或在这条会话继续追问。</p><button class="query-report-button">查看运行报告 →</button></div><div class="query-followups">'+['说明处理依据','查看风险说明','调整自动运行要求'].map(x=>'<button type="button">'+x+'</button>').join('')+'</div>';messages.append(report);report.querySelector('.query-report-button').onclick=()=>openPane(key);report.querySelectorAll('.query-followups button').forEach(b=>b.onclick=()=>{suggest('请'+b.textContent+'：'+d.title);promptBox.focus()});if(show)openPane(key);const entry=sessionRecords.find(s=>s.id===currentSessionId);if(entry){entry.resultType=key;saveSessionRecords()}document.getElementById('chatlog').scrollTop=0}
window.openBusinessQuery=function(key,index){const d=data[key];openNewConversation();selectedComposerAgent=key==='material'?'production-ops-agent':key==='purchase'?'purchase-fulfillment-agent':key==='sales'?'order-ops-agent':'inventory-ops-agent';document.getElementById('agent-toggle').textContent=d.agent;document.getElementById('agent-toggle').dataset.selectedAgent=selectedComposerAgent;document.getElementById('title').textContent=d.title;const row=Number.isInteger(index)?d.rows[index]:null;const text=key==='material'?'已查询主控板 PCB-A100 的物料编码、规格、单位及状态，可在右侧查看结果。':(row?'已定位 '+row[0]+'，':'')+'已整理'+d.title+'，共 '+d.rows.length+' 条示例数据，可在右侧查看明细。';addMessage(text,false);const entry=sessionRecords.find(s=>s.id===currentSessionId);if(entry){entry.title=key==='material'?'物料信息查询':d.title;saveSessionRecords();renderSessionHistory()}addReport(key);promptBox.placeholder='可以确认建议，也可以继续追问依据、修改字段或说明你的要求…'};
const restoreBase=openSavedSession;openSavedSession=function(id){restoreBase(id);const entry=sessionRecords.find(s=>s.id===id);if(!entry||entry.title==='查询库存现有量及可用量')return;activate();const key=entry.resultType||(/物料信息|查询物料/.test(entry.title)?'material':/待交付采购/.test(entry.title)?'purchase':/销售订单查询/.test(entry.title)?'sales':/库存现有量/.test(entry.title)?'stock':null);if(key&&data[key]){const author=messages.querySelector('.chatmessage:not(.user-message)>strong');if(author)author.textContent=data[key].agent;document.getElementById('agent-toggle').textContent=data[key].agent;addReport(key)}promptBox.placeholder='可以确认建议，也可以继续追问依据、修改字段或说明你的要求…'};
const sendBase=sendPrompt;sendPrompt=function(){const q=promptBox.value.trim();if(!q)return sendBase();if(/查询物料|物料信息|物料编码/.test(q)&&!aiFiles.length){addMessage(q,true);promptBox.value='';refreshSend();addMessage('已查询主控板 PCB-A100 与铝制外壳 HSG-A100 的物料编码、规格、单位及状态。',false);addReport('material');return}if(messages.querySelector('.query-run-report')&&/处理依据|风险说明|自动运行要求|解释/.test(q)){addMessage(q,true);promptBox.value='';refreshSend();const answer=/风险/.test(q)?'本次为只读查询，未修改物料或库存数据。结果使用示例数据；实际处理前请复核库存组织、物料版本、计量单位和业务截止时间。':/自动运行/.test(q)?'请补充期望的执行频率、执行时间和查询范围，我会先整理调整要求，确认后再进行配置。':resultKey==='material'?'本次按物料编码匹配基础资料，整理名称、规格、主计量单位及有效状态。PCB-A100 为主控板，规格为 A100 标准控制板，单位为块；HSG-A100 为铝制外壳，单位为套。':'已按当前业务查询范围整理结果。请结合单据编码、物料、库存组织与业务日期核对；右侧表格可分页查看明细。';addMessage(answer,false);return}sendBase()};
window.addEventListener('message',e=>{const iframe=document.querySelector('#market-view iframe');if(e.origin!==location.origin||e.source!==iframe?.contentWindow||e.data?.type!=='erp-directory-start'||e.data.kind!=='agent')return;selectedComposerAgent=e.data.id;const toggle=document.getElementById('agent-toggle');toggle.textContent=e.data.name;toggle.title=e.data.name;toggle.dataset.selectedAgent=e.data.id;delete toggle.dataset.selectedSkill;document.getElementById('title').textContent=e.data.name;document.getElementById('subtitle').textContent=e.data.desc||'';promptBox.focus()});
})();
